		"event":               "read_bytes_probe",
		"alias":               "retained_bytes",
		"pending":             len(r.pendingReadIndexMessages),
		"retained_ctx_bytes":  retained,
		"distinct_ctx_buffers": len(distinct),
		"ctx_bytes":           ctxBytes,
		"rounds":              rounds,
